#!/usr/bin/env node
/**
 * Reads `supabase status -o env` and writes the local .env files for web, mobile
 * and functions. Mobile uses the machine's LAN IP (not 127.0.0.1) so Expo Go on a
 * physical phone can reach local Supabase. Never overwrites real keys you've added
 * below the AUTO-GENERATED marker.
 */
import { execSync } from 'node:child_process';
import { existsSync, writeFileSync } from 'node:fs';
import { networkInterfaces } from 'node:os';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');

function supabaseStatusEnv() {
  const out = execSync('pnpm exec supabase status -o env', { cwd: root, encoding: 'utf8' });
  const env = {};
  for (const line of out.split('\n')) {
    const m = line.match(/^([A-Z0-9_]+)="?(.*?)"?$/);
    if (m) env[m[1]] = m[2];
  }
  return env;
}

function lanIp() {
  const nets = networkInterfaces();
  for (const name of Object.keys(nets)) {
    for (const net of nets[name] ?? []) {
      if (net.family === 'IPv4' && !net.internal) return net.address;
    }
  }
  return '127.0.0.1';
}

const status = supabaseStatusEnv();
const apiUrl = status.API_URL || 'http://127.0.0.1:54321';
const anon = status.ANON_KEY || '';
const serviceRole = status.SERVICE_ROLE_KEY || '';

if (!anon) {
  console.error('✗ Could not read ANON_KEY from `supabase status`. Is Supabase running?');
  process.exit(1);
}

const ip = lanIp();
const mobileApiUrl = apiUrl.replace('127.0.0.1', ip).replace('localhost', ip);
const marker = '# ---- AUTO-GENERATED by pnpm setup:local (safe to re-run) ----';

// apps/web/.env.local
writeEnv(join(root, 'apps', 'web', '.env.local'), [
  marker,
  'INTEGRATIONS_MODE=auto',
  'NEXT_PUBLIC_APP_NAME=Darjeeling Momo',
  `NEXT_PUBLIC_SUPABASE_URL=${apiUrl}`,
  `NEXT_PUBLIC_SUPABASE_ANON_KEY=${anon}`,
  '# Server-only (never exposed to the browser):',
  `SUPABASE_URL=${apiUrl}`,
  `SUPABASE_SERVICE_ROLE_KEY=${serviceRole}`,
  '# Add real keys below to switch services on (see INTEGRATIONS.md):',
  '# NEXT_PUBLIC_GOOGLE_AUTH_ENABLED=true',
  '# NEXT_PUBLIC_STRIPE_PUBLISHABLE_KEY=pk_test_...',
]);

// apps/mobile/.env  (LAN IP so a phone on the same Wi-Fi can reach Supabase)
writeEnv(join(root, 'apps', 'mobile', '.env'), [
  marker,
  'EXPO_PUBLIC_INTEGRATIONS_MODE=auto',
  'EXPO_PUBLIC_APP_NAME=Darjeeling Momo',
  `EXPO_PUBLIC_SUPABASE_URL=${mobileApiUrl}`,
  `EXPO_PUBLIC_SUPABASE_ANON_KEY=${anon}`,
  `# Web origin used to resolve relative menu image paths on the device:`,
  `EXPO_PUBLIC_WEB_ORIGIN=http://${ip}:3000`,
  '# Add real keys below to switch services on (see INTEGRATIONS.md):',
  '# EXPO_PUBLIC_GOOGLE_AUTH_ENABLED=true',
  '# EXPO_PUBLIC_APPLE_AUTH_ENABLED=true',
  '# EXPO_PUBLIC_STRIPE_PUBLISHABLE_KEY=pk_test_...',
  '# EXPO_PUBLIC_EAS_PROJECT_ID=...',
]);

// supabase/functions/.env  (local: CLI injects SUPABASE_* automatically)
const fnEnv = join(root, 'supabase', 'functions', '.env');
if (!existsSync(fnEnv)) {
  writeEnv(fnEnv, [
    '# Local functions env. SUPABASE_* are injected by the CLI.',
    '# Add Stripe keys here to switch payments to real (see INTEGRATIONS.md §4):',
    '# STRIPE_SECRET_KEY=sk_test_...',
    '# STRIPE_WEBHOOK_SECRET=whsec_...',
    '# STRIPE_PUBLISHABLE_KEY=pk_test_...',
  ]);
}

console.log('✓ Wrote local env files:');
console.log('   apps/web/.env.local');
console.log(`   apps/mobile/.env   (Supabase URL -> ${mobileApiUrl})`);
console.log('   supabase/functions/.env');

function writeEnv(path, lines) {
  writeFileSync(path, lines.join('\n') + '\n');
}
